 "uz": "2 shoxcha", "tk": "2 şaha", "ky": "2 бутак", "ka": "2 ტოტი"}}, {"name": {"az": "Zeytun yağı", "ru": "Оливковое масло", "en": "Olive oil", "tr": "Zeytinyağı", "kk": "Зәйтүн майы", "uz": "Zaytun moyi", "tk": "Zeýtun ýagy", "ky": "Зайтун майы", "ka": "ზეითუნის ზეთი"}, "amount": {"az": "1 xörək qaşığı", "ru": "1 ст. л.", "en": "1 tbsp", "tr": "1 yemek kaşığı", "kk": "1 ас қасық", "uz": "1 osh qoshiq", "tk": "1 nahar çemçesi", "ky": "1 аш кашык", "ka": "1 სუფრის კოვზი"}}, {"name": {"az": "Nar dənəsi", "ru": "Зёрна граната", "en": "Pomegranate seeds", "tr": "Nar taneleri", "kk": "Анар дәні", "uz": "Anor donasi", "tk": "Nar dänesi", "ky": "Анар данеги", "ka": "ბროწეულის მარცვლები"}, "amount": {"az": "2 xörək qaşığı", "ru": "2 ст. л.", "en": "2 tbsp", "tr": "2 yemek kaşığı", "kk": "2 ас қасық", "uz": "2 osh qoshiq", "tk": "2 nahar çemçesi", "ky": "2 аш кашык", "ka": "2 სუფრის კოვზი"}}, {"name": {"az": "Duz, istiot", "ru": "Соль, перец", "en": "Salt, pepper", "tr": "Tuz, karabiber", "kk": "Тұз, бұрыш", "uz": "Tuz, murch", "tk": "Duz, burç", "ky": "Туз, мурч", "ka": "მარილი, პილპილი"}, "amount": {"az": "az", "ru": "по вкусу", "en": "to taste", "tr": "az", "kk": "аздап", "uz": "taʼbga koʻra", "tk": "azajyk", "ky": "аз", "ka": "ცოტა"}}], "steps": [{"az": "Pirzolanı duz, istiot, əzilmiş sarımsaq və rozmarinlə ovuşdurub 15 dəqiqə saxla.", "ru": "Натри мясо солью, перцем, давленым чесноком и розмарином, оставь на 15 минут.", "en": "Rub the chops with salt, pepper, crushed garlic and rosemary; rest 15 minutes.", "tr": "Pirzolaları tuz, karabiber, ezilmiş sarımsak ve biberiyeyle ovup 15 dakika beklet.", "kk": "Қабырғаларды тұз, бұрыш, езілген сарымсақ және розмаринмен ысқылап, 15 минут қалдыр.", "uz": "Qovurgʻalarni tuz, murch, ezilgan sarimsoq va rozmarin bilan ishqalab, 15 daqiqa qoldir.", "tk": "Gapyrgany duz, burç, ezilen sarymsak we rozmarin bilen owkalap, 15 minut sakla.", "ky": "Кабырганы туз, мурч, эзилген сарымсак жана розмарин менен сүртүп, 15 мүнөт турсун.", "ka": "ნეკნები მარილით, პილპილით, დაჭყლეტილი ნივრითა და როზმარინით დაზილე და 15 წუთი დატოვე."}, {"az": "Yaxşı qızmış tavada hər tərəfdən 3–4 dəqiqə qızart, sonra 5 dəqiqə dincəlməyə qoy.", "ru": "Обжарь на хорошо разогретой сковороде по 3–4 минуты с каждой стороны, дай отдохнуть 5 минут.", "en": "Sear in a very hot pan for 3–4 minutes per side, then rest 5 minutes.", "tr": "İyice ısınmış tavada her iki tarafını 3–4 dakika kızart, sonra 5 dakika dinlendir.", "kk": "Жақсы қызған табада әр жағын 3–4 минут қуырып, содан кейін 5 минут демалуға қой.", "uz": "Yaxshi qizigan tovada har tomonini 3–4 daqiqadan qovur, keyin 5 daqiqa dam olishga qoʻy.", "tk": "Gowy gyzan tawada her tarapyny 3–4 minut gowur, soňra 5 minut dynç almaga goý.", "ky": "Жакшы ысыган табада ар тарабын 3–4 мүнөттөн кууруп, андан кийин 5 мүнөт эс алдыр.", "ka": "კარგად გაცხელებულ ტაფაზე თითო მხარე 3–4 წუთი შეწვი, შემდეგ 5 წუთი დაასვენე."}, {"az": "Həmin tavaya narşərab və 2 xörək qaşığı su əlavə edib 1 dəqiqə qaynat.", "ru": "Влей в ту же сковороду наршараб и 2 ст. л. воды, прокипяти 1 минуту.", "en": "Add narsharab and 2 tbsp water to the pan and bubble for 1 minute.", "tr": "Aynı tavaya narşarap ve 2 yemek kaşığı su ekleyip 1 dakika kaynat.", "kk": "Сол табаға наршараб пен 2 ас қасық су қосып, 1 минут қайнат.", "uz": "Oʻsha tovaga narsharab va 2 osh qoshiq suv qoʻshib, 1 daqiqa qaynat.", "tk": "Şol tawa narşarab we 2 nahar çemçesi suw goşup, 1 minut gaýnat.", "ky": "Ошол эле табага наршараб жана 2 аш кашык суу кошуп, 1 мүнөт кайнат.", "ka": "იმავე ტაფაში დაამატე ნარშარაბი და 2 სუფრის კოვზი წყალი და 1 წუთი ადუღე."}, {"az": "Sousu ətin üstünə tök, nar dənəsi ilə bəzə.", "ru": "Полей мясо соусом и укрась зёрнами граната.", "en": "Spoon the glaze over the lamb and scatter with pomegranate seeds.", "tr": "Sosu etin üzerine dök, nar taneleriyle süsle.", "kk": "Тұздықты еттің үстіне құйып, анар дәнімен безенді.", "uz": "Sousni goʻsht ustiga quy, anor donasi bilan bezat.", "tk": "Sousy etiň üstüne guý, nar dänesi bilen bezä.", "ky": "Соусту эттин үстүнө куюп, анар данеги менен кооздо.", "ka": "სოუსი ხორცს გადაასხი და ბროწეულის მარცვლებით მორთე."}], "allergens": []}',
