    '{"title": {"az": "Yaşıl mərci, bişmiş balqabaq və feta salatı", "ru": "Салат из зелёной чечевицы, печёной тыквы и феты", "en": "Green lentil, roasted pumpkin and feta salad", "tr": "Yeşil mercimek, fırın balkabağı ve feta salatası", "kk": "Жасыл жасымық, пісірілген асқабақ және фета салаты", "uz": "Yashil yasmiq, pishirilgan qovoq va feta salati", "tk": "Ýaşyl merjimek, bişirilen kädi we feta salady", "ky": "Жашыл жасмык, бышырылган ашкабак жана фета салаты", "ka": "მწვანე ოსპის, გამომცხვარი გოგრისა და ფეტას სალათი"}, "minutes": 35, "servings": 3, "groups": ["vegetables", "protein", "healthy_fat", "dairy"], "ingredients": [{"name": {"az": "Yaşıl mərci", "ru": "Зелёная чечевица", "en": "Green lentils", "tr": "Yeşil mercimek", "kk": "Жасыл жасымық", "uz": "Yashil yasmiq", "tk": "Ýaşyl merjimek", "ky": "Жашыл жасмык", "ka": "მწვანე ოსპი"}, "amount": {"az": "¾ stəkan", "ru": "¾ стакана", "en": "¾ cup", "tr": "¾ su bardağı", "kk": "¾ стақан", "uz": "¾ stakan", "tk": "¾ stakan", "ky": "¾ стакан", "ka": "¾ ჭიქა"}}, {"name": {"az": "Balqabaq (kub)", "ru": "Тыква (кубиками)", "en": "Pumpkin (cubed)", "tr": "Balkabağı (küp)", "kk": "Асқабақ (текшеленген)", "uz": "Qovoq (kubik)", "tk": "Kädi (kub edilen)", "ky": "Ашкабак (куб)", "ka": "გოგრა (კუბიკებად)"}, "amount": {"az": "300 q", "ru": "300 г", "en": "300 g", "tr": "300 gr", "kk": "300 г", "uz": "300 g", "tk": "300 g", "ky": "300 г", "ka": "300 გ"}}, {"name": {"az": "Feta", "ru": "Фета", "en": "Feta", "tr": "Feta peyniri", "kk": "Фета", "uz": "Feta", "tk": "Feta", "ky": "Фета", "ka": "ფეტა"}, "amount": {"az": "60 q", "ru": "60 г", "en": "60 g", "tr": "60 gr", "kk": "60 г", "uz": "60 g", "tk": "60 g", "ky": "60 г", "ka": "60 გ"}}, {"name": {"az": "Ispanaq", "ru": "Шпинат", "en": "Spinach", "tr": "Ispanak", "kk": "Шпинат", "uz": "Ismaloq", "tk": "Ysmanak", "ky": "Шпинат", "ka": "ისპანახი"}, "amount": {"az": "2 ovuc", "ru": "2 горсти", "en": "2 handfuls", "tr": "2 avuç", "kk": "2 уыс", "uz": "2 hovuch", "tk": "2 owuç", "ky": "2 ууч", "ka": "2 მუჭა"}}, {"name": {"az": "Balqabaq tumu", "ru": "Тыквенные семечки", "en": "Pumpkin seeds", "tr": "Kabak çekirdeği", "kk": "Асқабақ дәні", "uz": "Qovoq pistasi", "tk": "Kädi tohumy", "ky": "Ашкабак уругу", "ka": "გოგრის თესლი"}, "amount": {"az": "1 xörək qaşığı", "ru": "1 ст. л.", "en": "1 tbsp", "tr": "1 yemek kaşığı", "kk": "1 ас қасық", "uz": "1 osh qoshiq", "tk": "1 nahar çemçesi", "ky": "1 аш кашык", "ka": "1 სუფრის კოვზი"}}, {"name": {"az": "Limon", "ru": "Лимон", "en": "Lemon", "tr": "Limon", "kk": "Лимон", "uz": "Limon", "tk": "Limon", "ky": "Лимон", "ka": "ლიმონი"}, "amount": {"az": "½ ədəd", "ru": "½ шт.", "en": "½", "tr": "½ adet", "kk": "½ дана", "uz": "½ dona", "tk": "½ sany", "ky": "½ даана", "ka": "½ ცალი"}}, {"name": {"az": "Zeytun yağı", "ru": "Оливковое масло", "en": "Olive oil", "tr": "Zeytinyağı", "kk": "Зәйтүн майы", "uz": "Zaytun moyi", "tk": "Zeýtun ýagy", "ky": "Зайтун майы", "ka": "ზეითუნის ზეთი"}, "amount": {"az": "2 xörək qaşığı", "ru": "2 ст. л.", "en": "2 tbsp", "tr": "2 yemek kaşığı", "kk": "2 ас қасық", "uz": "2 osh qoshiq", "tk": "2 nahar çemçesi", "ky": "2 аш кашык", "ka": "2 სუფრის კოვზი"}}, {"name": {"az": "Duz, istiot", "ru": "Соль, перец", "en": "Salt, pepper", "tr": "Tuz, karabiber", "kk": "Тұз, бұрыш", "uz": "Tuz, murch", "tk": "Duz, burç", "ky": "Туз, мурч", "ka": "მარილი, პილპილი"}, "amount": {"az": "az", "ru": "по вкусу", "en": "to taste", "tr": "az", "kk": "аздап", "uz": "taʼbga koʻra", "tk": "azajyk", "ky": "аз", "ka": "ცოტა"}}], "steps": [{"az": "Mərcini 20–25 dəqiqə yumşalana qədər qaynadıb süz.", "ru": "Отвари чечевицу 20–25 минут до мягкости, откинь.", "en": "Simmer the lentils 20–25 minutes until tender; drain.", "tr": "Mercimeği 20–25 dakika yumuşayana kadar haşlayıp süz.", "kk": "Жасымықты 20–25 минут жұмсарғанша қайнатып, сүзгіден өткіз.", "uz": "Yasmiqni 20–25 daqiqa yumshaguncha qaynatib, suvini sizdir.", "tk": "Merjimegi 20–25 minut ýumşaýança gaýnadyp süz.", "ky": "Жасмыкты 20–25 мүнөт жумшарганча кайнатып, сүзүп ал.", "ka": "ოსპი 20–25 წუთი, დარბილებამდე მოხარშე და გადაწურე."}, {"az": "Balqabağı 1 xörək qaşığı yağla qarışdırıb 200°C sobada 20 dəqiqə bişir.", "ru": "Смешай тыкву с 1 ст. л. масла и запекай при 200°C 20 минут.", "en": "Toss the pumpkin with 1 tbsp oil and roast at 200°C for 20 minutes.", "tr": "Balkabağını 1 yemek kaşığı yağla karıştırıp 200°C fırında 20 dakika pişir.", "kk": "Асқабақты 1 ас қасық маймен араластырып, 200°C пеште 20 минут пісір.", "uz": "Qovoqni 1 osh qoshiq moy bilan aralashtirib, 200°C duxovkada 20 daqiqa pishir.", "tk": "Kädini 1 nahar çemçesi ýag bilen garyşdyryp, 200°C peçde 20 minut bişir.", "ky": "Ашкабакты 1 аш кашык май менен аралаштырып, 200°C духовкада 20 мүнөт бышыр.", "ka": "გოგრა 1 სუფრის კოვზ ზეთში აურიე და 200°C ღუმელში 20 წუთი გამოაცხვე."}, {"az": "Mərci, balqabaq və ispanağı qalan yağ və limonla qarışdır.", "ru": "Соедини чечевицу, тыкву и шпинат с оставшимся маслом и лимоном.", "en": "Combine lentils, pumpkin and spinach with the remaining oil and lemon.", "tr": "Mercimek, balkabağı ve ıspanağı kalan yağ ve limonla karıştır.", "kk": "Жасымық, асқабақ және шпинатты қалған май мен лимонмен араластыр.", "uz": "Yasmiq, qovoq va ismaloqni qolgan moy va limon bilan aralashtir.", "tk": "Merjimegi, kädini we ysmanagy galan ýag we limon bilen garyşdyr.", "ky": "Жасмыкты, ашкабакты жана шпинатты калган май жана лимон менен аралаштыр.", "ka": "ოსპი, გოგრა და ისპანახი დარჩენილ ზეთსა და ლიმონთან აურიე."}, {"az": "Üstünə xırdalanmış feta və tum səp.", "ru": "Посыпь раскрошенной фетой и семечками.", "en": "Top with crumbled feta and seeds.", "tr": "Üzerine ufalanmış feta ve kabak çekirdeği serp.", "kk": "Үстіне үгітілген фета мен дән сеп.", "uz": "Ustiga ushatilgan feta va pista sep.", "tk": "Üstüne owradylan feta we tohum sep.", "ky": "Үстүнө майдаланган фета жана урук сеп.", "ka": "ზემოდან მოაყარე დამტვრეული ფეტა და თესლი."}], "allergens": ["milk"]}',
