k": "¼ шай қасық", "uz": "¼ choy qoshiq", "tk": "¼ çaý çemçesi", "ky": "¼ чай кашык", "ka": "¼ ჩაის კოვზი"}}, {"name": {"az": "Duz", "ru": "Соль", "en": "Salt", "tr": "Tuz", "kk": "Тұз", "uz": "Tuz", "tk": "Duz", "ky": "Туз", "ka": "მარილი"}, "amount": {"az": "1 çimdik", "ru": "1 щепотка", "en": "1 pinch", "tr": "1 tutam", "kk": "1 шымшым", "uz": "1 chimdim", "tk": "1 çümmük", "ky": "1 чымчым", "ka": "1 პრეზი"}}, {"name": {"az": "Küncüt", "ru": "Кунжут", "en": "Sesame seeds", "tr": "Susam", "kk": "Күнжіт", "uz": "Kunjut", "tk": "Künji", "ky": "Кунжут", "ka": "სეზამი"}, "amount": {"az": "1 xörək qaşığı", "ru": "1 ст. л.", "en": "1 tbsp", "tr": "1 yemek kaşığı", "kk": "1 ас қасық", "uz": "1 osh qoshiq", "tk": "1 nahar çemçesi", "ky": "1 аш кашык", "ka": "1 სუფრის კოვზი"}}], "steps": [{"az": "Sobanı 175°C-yə qızdır.", "ru": "Разогрей духовку до 175°C.", "en": "Heat the oven to 175°C.", "tr": "Fırını 175°C\'ye ısıt.", "kk": "Пешті 175°C-қа дейін қыздыр.", "uz": "Duxovkani 175°C gacha qizdir.", "tk": "Peçi 175°C-e çenli gyzdyr.", "ky": "Духовканы 175°C чейин ысыт.", "ka": "ღუმელი 175°C-მდე გააცხელე."}, {"az": "Bütün tərkibi (küncütdən başqa) qarışdırıb yumşaq kütlə al.", "ru": "Смешай все ингредиенты, кроме кунжута, в мягкую массу.", "en": "Mix everything except the sesame into a soft dough.", "tr": "Susam hariç tüm malzemeleri karıştırıp yumuşak bir hamur elde et.", "kk": "Барлық құрамды (күнжіттен басқасын) араластырып, жұмсақ масса ал.", "uz": "Barcha masalliqlarni (kunjutdan tashqari) aralashtirib, yumshoq massa hosil qil.", "tk": "Ähli düzümi (künjiden başga) garyşdyryp, ýumşak garyndy al.", "ky": "Бардык азыктарды (кунжуттан башкасын) аралаштырып, жумшак масса жаса.", "ka": "ყველა ინგრედიენტი (სეზამის გარდა) აურიე და რბილი მასა მიიღე."}, {"az": "14 top düzəlt, küncütə batır, yağlı kağıza qoyub bir az bas.", "ru": "Скатай 14 шариков, обваляй в кунжуте, выложи на пергамент и слегка придави.", "en": "Roll into 14 balls, dip in sesame, place on a lined tray and flatten slightly.", "tr": "14 top yap, susama batır, yağlı kâğıda koyup hafifçe bastır.", "kk": "14 домалақ жасап, күнжітке малып, пергамент қағазына қойып, сәл басып жалпайт.", "uz": "14 ta shar yasab, kunjutga botir, pergament qogʻozga qoʻyib biroz bos.", "tk": "14 togalak ýasa, künjä batyr, pergament kagyza goýup, azajyk bas.", "ky": "14 тоголок жасап, кунжутка малып, май кагазга коюп, бир аз бас.", "ka": "გააკეთე 14 ბურთულა, სეზამში ამოავლე, საცხობ ქაღალდზე დაალაგე და ოდნავ დააჭირე."}, {"az": "10–12 dəqiqə bişir, sinidə soyut.", "ru": "Выпекай 10–12 минут, остуди на противне.", "en": "Bake 10–12 minutes and cool on the tray.", "tr": "10–12 dakika pişir, tepside soğut.", "kk": "10–12 минут пісіріп, табада суыт.", "uz": "10–12 daqiqa pishir, patnisda sovit.", "tk": "10–12 minut bişir, tabakda sowat.", "ky": "10–12 мүнөт бышырып, табакта муздат.", "ka": "10–12 წუთი გამოაცხვე და ფირფიტაზე გააცივე."}], "allergens": ["egg", "nuts", "sesame"]}',
  ),
  SeedContent(
    'recipe',
    'thyme-chicken-celeriac',
    'dinner',
    '{"title": {"az": "Kərəviz püresi və göyərti yağı ilə kəklikotulu toyuq", "ru": "Курица с тимьяном, пюре из сельдерея и зелёным маслом", "en": "Thyme chicken with celeriac purée and herb oil", "tr": "Kereviz püresi ve yeşillik yağıyla kekikli tavuk", "kk": "Балдыркөк пюресі және көк шөп майымен тимьянды тауық", "uz": "Selderey pyuresi va koʻkat moyi bilan togʻjambilli tovuq", "tk": "Kereweý püresi we gök ot ýagy bilen kekikli towuk", "ky": "Сельдерей пюреси жана жашылча чөп майы менен тимьян кошулган тоок", "ka": "თიმიანიანი ქათამი ნიახურის ძირის პიურეთი და მწვანილის ზეთით"}, "minutes": 45, "servings": 2, "groups": ["vegetables", "protein", "dairy"], "ingredients": [{"name": {"az": "Toyuq döşü", "ru": "Куриная грудка", "en": "Chicken breast", "tr": "Tavuk göğsü", "kk": "Тауық төсі", "uz": "Tovuq toʻshi", "tk": "Towuk döşi", "ky": "Тоок төшү", "ka": "ქათმის მკერდი"}, "amount": {"az": "2 ədəd", "ru": "2 шт.", "en": "2", "tr": "2 adet", "kk": "2 дана", "uz": "2 dona", "tk": "2 sany", "ky": "2 даана", "ka": "2 ცალი"}}, {"name": {"az": "Kərəviz kökü", "ru": "Корень сельдерея", "en": "Celeriac", "tr": "Kök kereviz", "kk": "Балдыркөк тамыры", "uz": "Selderey ildizi", "tk": "Kereweý köki", "ky": "Сельдерей тамыры", "ka": "ნიახურის ძირი"}, "amount": {"az": "400 q", "ru": "400 г", "en": "400 g", "tr": "400 gr", "kk": "400 г", "uz": "400 g", "tk": "400 g", "ky": "400 г", "ka": "400 გ"}}, {"name": {"az": "Süd", "ru": "Молоко", "en": "Milk", "tr": "Süt", "kk": "Сүт", "uz": "Sut", "tk": "Süýt", "ky": "Сүт", "ka": "რძე"}, "amount": {"az": "½ stəkan", "ru": "½ стакана", "en": "½ cup", "tr": "½ su bardağı", "kk": "½ стақан", "uz": "½ stakan", "tk": "½ stakan", "ky": "½ стакан", "ka": "½ ჭიქა"}}, {"name": {"az": "Kəklikotu", "ru": "Тимьян", "en": "Thyme", "tr": "Kekik", "kk": "Тимьян", "uz": "Togʻjambil", "tk": "Kekik (timýan)", "ky": "Тимьян", "ka": "თიმიანი"}, "amount": {"az": "4 budaq", "ru": "4 веточки", "en": "4 sprigs", "tr": "4 dal", "kk": "4 бұтақ", "uz": "4 shoxcha", "tk": "4 şaha", "ky": "4 бутак", "ka": "4 ტოტი"}}, {"name": {"az": "Cəfəri", "ru": "Петрушка", "en": "Parsley", "tr": "Maydanoz", "kk": "Ақжелкен", "uz": "Petrushka", "tk": "Petruşka", "ky": "Петрушка", "ka": "ოხრახუში"}, "amount": {"az": "1 ovuc", "ru": "1 горсть", "en": "1 handful", "tr": "1 avuç", "kk": "1 уыс", "uz": "1 hovuch", "tk": "1 owuç", "ky": "1 ууч", "ka": "1 მუჭა"}}, {"name": {"az": "Zeytun yağı", "ru": "Оливковое масло", "en": "Olive oil", "tr": "Zeytinyağı", "kk": "Зәйтүн майы", "uz": "Zaytun moyi", "tk": "Zeýtun ýagy", "ky": "Зайтун майы", "ka": "ზეითუნის ზეთი"}, "amount": {"az": "3 xörək qaşığı", "ru": "3 ст. л.", "en": "3 tbsp", "tr": "3 yemek kaşığı", "kk": "3 ас қасық", "uz": "3 osh qoshiq", "tk": "3 nahar çemçesi", "ky": "3 аш кашык", "ka": "3 სუფრის კოვზი"}}, {"name": {"az": "Sarımsaq", "ru": "Чеснок", "en": "Garlic", "tr": "Sarımsak", "kk": "Сарымсақ", "uz": "Sarimsoq", "tk": "Sarymsak", "ky": "Сарымсак", "ka": "ნიორი"}, "amount": {"az": "1 diş", "ru": "1 зубчик", "en": "1 clove", "tr": "1 diş", "kk": "1 тісі", "uz": "1 boʻlak", "tk": "1 diş", "ky": "1 тиш", "ka": "1 კბილი"}}, {"name": {"az": "Duz, istiot", "ru": "Соль, перец", "en": "Salt, pepper", "tr": "Tuz, karabiber", "kk": "Тұз, бұрыш", "uz": "Tuz, murch", "tk": "Duz, burç", "ky": "Туз, мурч", "ka": "მარილი, პილპილი"}, "amount": {"az": "az", "ru": "по вкусу", "en": "to taste", "tr": "az", "kk": "аздап", "uz": "taʼbga koʻra", "tk": "azajyk", "ky": "аз", "ka": "ცოტა"}}], "steps": [{"az": "Kərəviz kökünü doğrayıb südlə və yarım stəkan su ilə 20 dəqiqə yumşalana qədər bişir, püre et.", "ru": "Нарежь сельдерей и вари в молоке с полстаканом воды 20 минут до мягкости, сделай пюре.", "en": "Simmer cubed celeriac in the milk plus ½ cup water for 20 minutes until soft, then purée.", "tr": "Kerevizi doğrayıp süt ve yarım su bardağı suyla 20 dakika, yumuşayana kadar pişir, püre yap.", "kk": "Балдыркөк тамырын турап, сүт және жарты стақан сумен 20 минут жұмсарғанша пісіріп, пюре жаса.", "uz": "Selderey ildizini toʻgʻrab, sut va yarim stakan suvda 20 daqiqa yumshaguncha pishir, pyure qil.", "tk": "Kereweý köküni dograp, süýt we ýarym stakan suw bilen 20 minut ýumşaýança bişir, püre et.", "ky": "Сельдерей тамырын туурап, сүт жана жарым стакан суу менен 20 мүнөт жумшарганча бышырып, пюре жаса.", "ka": "ნიახურის ძირი დაჭერი, რძესა და ნახევარ ჭიქა წყალში 20 წუთი, დარბილებამდე მოხარშე და პიურედ აქციე."}, {"az": "Cəfərini 2 xörək qaşığı yağla blenderdə çalıb süz — göyərti yağı hazırdır.", "ru": "Пробей петрушку с 2 ст. л. масла и процеди — зелёное масло готово.", "en": "Blend the parsley with 2 tbsp oil and strain to make herb oil.", "tr": "Maydanozu 2 yemek kaşığı yağla blenderda çekip süz; yeşillik yağı hazır.", "kk": "Ақжелкенді 2 ас қасық маймен блендерде ұнтақтап, сүзгіден өткіз — көк шөп майы дайын.", "uz": "Petrushkani 2 osh qoshiq moy bilan blenderda aylantirib, suzib ol — koʻkat moyi tayyor.", "tk": "Petruşkany 2 nahar çemçesi ýag bilen blenderde çaýkap süz — gök ot ýagy taýýar.", "ky": "Петрушканы 2 аш кашык май менен блендерде майдалап, сүз — жашылча чөп майы даяр.", "ka": "ოხრახუში 2 სუფრის კოვზ ზეთთან ერთად ბლენდერში ათქვიფე და გადაწურე — მწვანილის ზეთი მზადაა."}, {"az": "Toyuğu duz, istiot, sarımsaq və kəklikotu ilə ovuşdur, tavada hər tərəfdən 6–7 dəqiqə, içi tam bişənə qədər qızart.", "ru": "Натри курицу солью, перцем, чесноком и тимьяном, обжарь по 6–7 минут с каждой стороны до полной готовности.", "en": "Rub the chicken with salt, pepper, garlic and thyme; pan-fry 6–7 minutes per side until cooked through.", "tr": "Tavuğu tuz, karabiber, sarımsak ve kekikle ov, tavada her iki tarafını 6–7 dakika, içi tamamen pişene kadar kızart.", "kk": "Тауықты тұз, бұрыш, сарымсақ және тимьянмен ысқылап, табада әр жағын 6–7 минут, іші толық піскенше қуыр.", "uz": "Tovuqni tuz, murch, sarimsoq va togʻjambil bilan ishqala, tovada har tomonini 6–7 daqiqadan, ichi toʻliq pishguncha qovur.", "tk": "Towugy duz, burç, sarymsak we kekik bilen owkala, tawada her tarapyny 6–7 minut, içi doly bişýänçä gowur.", "ky": "Тоокту туз, мурч, сарымсак жана тимьян менен сүртүп, табада ар тарабын 6–7 мүнөттөн, ичи толук бышканча кууру.", "ka": "ქათამი მარილით, პილპილით, ნივრითა და თიმიანით დაზილე, ტაფაზე თითო მხარე 6–7 წუთი, ბოლომდე შეწვამდე შეწვი."}, {"az": "Püreni boşqaba qoy, dilimlənmiş toyuğu üstünə düz, ətrafına göyərti yağı damcılat.", "ru": "Выложи пюре, сверху нарезанную курицу, вокруг — капли зелёного масла.", "en": "Spoon purée onto plates, top with sliced chicken and dot herb oil around.", "tr": "Püreyi tabağa koy, dilimlenmiş tavuğu üzerine diz, etrafına yeşillik yağı damlat.", "kk": "Пюрені табаққа салып, үстіне тілімделген тауықты тізіп, айналасына көк шөп майын тамызып шық.", "uz": "Pyureni likopchaga qoʻy, tilimlangan tovuqni ustiga ter, atrofiga koʻkat moyidan tomizib chiq.", "tk": "Püräni tabaga goý, dilimlenen towugy üstüne düz, töweregine gök ot ýagyny damjalat.", "ky": "Пюрени табакка салып, тилимделген тоокту үстүнө тизип, айланасына жашылча чөп майын тамчылат.", "ka": "პიურე თეფშზე დადე, ზემოდან დაჭრილი ქათამი დაალაგე, გარშემო მწვანილის ზეთი დააწვეთე."}], "allergens": ["milk", "celery"]}',
  ),
