"uz": "Tomat pastasi", "tk": "Pomidor pastasy", "ky": "Помидор пастасы", "ka": "ტომატის პასტა"}, "amount": {"az": "1 xörək qaşığı", "ru": "1 ст. л.", "en": "1 tbsp", "tr": "1 yemek kaşığı", "kk": "1 ас қасық", "uz": "1 osh qoshiq", "tk": "1 nahar çemçesi", "ky": "1 аш кашык", "ka": "1 სუფრის კოვზი"}}, {"name": {"az": "Limon", "ru": "Лимон", "en": "Lemon", "tr": "Limon", "kk": "Лимон", "uz": "Limon", "tk": "Limon", "ky": "Лимон", "ka": "ლიმონი"}, "amount": {"az": "1 ədəd", "ru": "1 шт.", "en": "1", "tr": "1 adet", "kk": "1 дана", "uz": "1 dona", "tk": "1 sany", "ky": "1 даана", "ka": "1 ცალი"}}, {"name": {"az": "Zeytun yağı", "ru": "Оливковое масло", "en": "Olive oil", "tr": "Zeytinyağı", "kk": "Зәйтүн майы", "uz": "Zaytun moyi", "tk": "Zeýtun ýagy", "ky": "Зайтун майы", "ka": "ზეითუნის ზეთი"}, "amount": {"az": "3 xörək qaşığı", "ru": "3 ст. л.", "en": "3 tbsp", "tr": "3 yemek kaşığı", "kk": "3 ас қасық", "uz": "3 osh qoshiq", "tk": "3 nahar çemçesi", "ky": "3 аш кашык", "ka": "3 სუფრის კოვზი"}}, {"name": {"az": "Duz, istiot", "ru": "Соль, перец", "en": "Salt, pepper", "tr": "Tuz, karabiber", "kk": "Тұз, бұрыш", "uz": "Tuz, murch", "tk": "Duz, burç", "ky": "Туз, мурч", "ka": "მარილი, პილპილი"}, "amount": {"az": "az", "ru": "по вкусу", "en": "to taste", "tr": "az", "kk": "аздап", "uz": "taʼbga koʻra", "tk": "azajyk", "ky": "аз", "ka": "ცოტა"}}], "steps": [{"az": "Yarpaqları qaynar suda 2 dəqiqə saxlayıb süz.", "ru": "Подержи листья в кипятке 2 минуты и откинь.", "en": "Blanch the leaves in boiling water for 2 minutes and drain.", "tr": "Yaprakları kaynar suda 2 dakika bekletip süz.", "kk": "Жапырақтарды қайнаған суда 2 минут ұстап, сүзгіден өткіз.", "uz": "Barglarni qaynoq suvda 2 daqiqa tutib, suvini sizdir.", "tk": "Ýapraklary gaýnag suwda 2 minut saklap süz.", "ky": "Жалбырактарды кайнак сууда 2 мүнөт кармап, сүзүп ал.", "ka": "ფოთლები მდუღარე წყალში 2 წუთი გააჩერე და გადაწურე."}, {"az": "Soğanı yağda yumşald, yuyulmuş düyü, pomidor pastası, göyərti və duzla qarışdır.", "ru": "Обжарь лук, смешай с промытым рисом, томатной пастой, зеленью и солью.", "en": "Soften the onion in oil and mix with rinsed rice, tomato paste, herbs and salt.", "tr": "Soğanı yağda yumuşat, yıkanmış pirinç, salça, yeşillikler ve tuzla karıştır.", "kk": "Пиязды майда жұмсартып, жуылған күріш, томат пастасы, көк шөп және тұзбен араластыр.", "uz": "Piyozni moyda yumshat, yuvilgan guruch, tomat pastasi, koʻkat va tuz bilan aralashtir.", "tk": "Sogany ýagda ýumşat, ýuwulan tüwi, pomidor pastasy, gök otlar we duz bilen garyşdyr.", "ky": "Пиязды майда жумшартып, жуулган күрүч, помидор пастасы, жашылча чөптөр жана туз менен аралаштыр.", "ka": "ხახვი ზეთში მოშუშე, აურიე გარეცხილ ბრინჯთან, ტომატის პასტასთან, მწვანილთან და მარილთან."}, {"az": "Hər yarpağa 1 çay qaşığı içlik qoyub sıx bük.", "ru": "На каждый лист положи 1 ч. л. начинки и плотно сверни.", "en": "Put 1 tsp filling on each leaf and roll tightly.", "tr": "Her yaprağa 1 çay kaşığı iç koyup sıkıca sar.", "kk": "Әр жапыраққа 1 шай қасық салма салып, тығыз ора.", "uz": "Har bir bargga 1 choy qoshiq ichlik qoʻyib, zich oʻra.", "tk": "Her ýapraga 1 çaý çemçesi iç goýup, berk dola.", "ky": "Ар бир жалбыракка 1 чай кашык ич салып, бекем ороп ал.", "ka": "თითოეულ ფოთოლზე 1 ჩაის კოვზი გულსართი დადე და მჭიდროდ დაახვიე."}, {"az": "Qazana sıx düz, limon dilimləri və 2 stəkan su əlavə et, boşqabla basıb zəif odda 50 dəqiqə bişir.", "ru": "Плотно уложи в кастрюлю, добавь ломтики лимона и 2 стакана воды, придави тарелкой и томи на слабом огне 50 минут.", "en": "Pack into a pot with lemon slices and 2 cups water, weigh down with a plate and simmer gently 50 minutes.", "tr": "Tencereye sıkıca diz, limon dilimleri ve 2 su bardağı su ekle, üzerine bir tabak bastırıp kısık ateşte 50 dakika pişir.", "kk": "Қазанға тығыз тізіп, лимон тілімдері мен 2 стақан су қосып, үстінен табақпен басып, баяу отта 50 минут пісір.", "uz": "Qozonga zich terib, limon tilimlari va 2 stakan suv qoʻsh, likopcha bilan bostirib, past olovda 50 daqiqa pishir.", "tk": "Gazana jebis düz, limon dilimlerini we 2 stakan suw goş, tabak bilen basyp, haýal otda 50 minut bişir.", "ky": "Казанга тыгыз тизип, лимон тилимдерин жана 2 стакан суу кошуп, табак менен басып, акырын отто 50 мүнөт бышыр.", "ka": "ქვაბში მჭიდროდ ჩაალაგე, დაუმატე ლიმონის ნაჭრები და 2 ჭიქა წყალი, თეფშით დააწექი და დაბალ ცეცხლზე 50 წუთი ხარშე."}], "allergens": []}',
