    '{"title": {"az": "Qatıqda marinadlanmış toyuq şişləri", "ru": "Шашлычки из курицы в йогуртовом маринаде", "en": "Yoghurt-marinated chicken skewers", "tr": "Yoğurtlu marine tavuk şiş", "kk": "Йогуртқа маринадталған тауық шашлығы", "uz": "Qatiqda marinadlangan tovuq kabobi", "tk": "Gatykda marinadlanan towuk şaşlygy", "ky": "Йогуртка маринаддалган тоок шишкебеги", "ka": "მაწონში დამარინადებული ქათმის შამფური"}, "minutes": 40, "servings": 6, "groups": ["vegetables", "protein", "dairy"], "ingredients": [{"name": {"az": "Toyuq budu (sümüksüz)", "ru": "Куриное бедро без кости", "en": "Boneless chicken thighs", "tr": "Tavuk but (kemiksiz)", "kk": "Тауық саны (сүйексіз)", "uz": "Tovuq soni (suyaksiz)", "tk": "Towuk budy (süýeksiz)", "ky": "Тоок санынын эти (сөөгүсүз)", "ka": "ქათმის ბარკალი (უძვლო)"}, "amount": {"az": "800 q", "ru": "800 г", "en": "800 g", "tr": "800 gr", "kk": "800 г", "uz": "800 g", "tk": "800 g", "ky": "800 г", "ka": "800 გ"}}, {"name": {"az": "Qatıq", "ru": "Йогурт", "en": "Plain yoghurt", "tr": "Yoğurt", "kk": "Йогурт", "uz": "Qatiq", "tk": "Gatyk", "ky": "Йогурт", "ka": "მაწონი"}, "amount": {"az": "1 stəkan", "ru": "1 стакан", "en": "1 cup", "tr": "1 su bardağı", "kk": "1 стақан", "uz": "1 stakan", "tk": "1 stakan", "ky": "1 стакан", "ka": "1 ჭიქა"}}, {"name": {"az": "Sarımsaq", "ru": "Чеснок", "en": "Garlic", "tr": "Sarımsak", "kk": "Сарымсақ", "uz": "Sarimsoq", "tk": "Sarymsak", "ky": "Сарымсак", "ka": "ნიორი"}, "amount": {"az": "3 diş", "ru": "3 зубчика", "en": "3 cloves", "tr": "3 diş", "kk": "3 тісі", "uz": "3 boʻlak", "tk": "3 diş", "ky": "3 тиш", "ka": "3 კბილი"}}, {"name": {"az": "Paprika", "ru": "Паприка", "en": "Paprika", "tr": "Toz kırmızı biber", "kk": "Паприка", "uz": "Paprika", "tk": "Paprika", "ky": "Паприка", "ka": "პაპრიკა"}, "amount": {"az": "2 çay qaşığı", "ru": "2 ч. л.", "en": "2 tsp", "tr": "2 çay kaşığı", "kk": "2 шай қасық", "uz": "2 choy qoshiq", "tk": "2 çaý çemçesi", "ky": "2 чай кашык", "ka": "2 ჩაის კოვზი"}}, {"name": {"az": "Limon", "ru": "Лимон", "en": "Lemon", "tr": "Limon", "kk": "Лимон", "uz": "Limon", "tk": "Limon", "ky": "Лимон", "ka": "ლიმონი"}, "amount": {"az": "1 ədəd", "ru": "1 шт.", "en": "1", "tr": "1 adet", "kk": "1 дана", "uz": "1 dona", "tk": "1 sany", "ky": "1 даана", "ka": "1 ცალი"}}, {"name": {"az": "Bolqar bibəri", "ru": "Болгарский перец", "en": "Bell peppers", "tr": "Dolmalık biber", "kk": "Болгар бұрышы", "uz": "Bolgar qalampiri", "tk": "Bolgar burçy", "ky": "Болгар калемпири", "ka": "ბულგარული წიწაკა"}, "amount": {"az": "2 ədəd", "ru": "2 шт.", "en": "2", "tr": "2 adet", "kk": "2 дана", "uz": "2 dona", "tk": "2 sany", "ky": "2 даана", "ka": "2 ცალი"}}, {"name": {"az": "Qırmızı soğan", "ru": "Красный лук", "en": "Red onion", "tr": "Kırmızı soğan", "kk": "Қызыл пияз", "uz": "Qizil piyoz", "tk": "Gyzyl sogan", "ky": "Кызыл пияз", "ka": "წითელი ხახვი"}, "amount": {"az": "1 ədəd", "ru": "1 шт.", "en": "1", "tr": "1 adet", "kk": "1 дана", "uz": "1 dona", "tk": "1 sany", "ky": "1 даана", "ka": "1 ცალი"}}, {"name": {"az": "Duz, istiot", "ru": "Соль, перец", "en": "Salt, pepper", "tr": "Tuz, karabiber", "kk": "Тұз, бұрыш", "uz": "Tuz, murch", "tk": "Duz, burç", "ky": "Туз, мурч", "ka": "მარილი, პილპილი"}, "amount": {"az": "az", "ru": "по вкусу", "en": "to taste", "tr": "az", "kk": "аздап", "uz": "taʼbga koʻra", "tk": "azajyk", "ky": "аз", "ka": "ცოტა"}}], "steps": [{"az": "Toyuğu kub doğra, qatıq, sarımsaq, paprika, limon və duzla qarışdırıb ən azı 2 saat soyuducuda saxla.", "ru": "Нарежь курицу кубиками, смешай с йогуртом, чесноком, паприкой, лимоном и солью, маринуй в холодильнике минимум 2 часа.", "en": "Cube the chicken and mix with yoghurt, garlic, paprika, lemon and salt; marinate in the fridge for at least 2 hours.", "tr": "Tavuğu küp doğra, yoğurt, sarımsak, toz kırmızı biber, limon ve tuzla karıştırıp en az 2 saat buzdolabında beklet.", "kk": "Тауықты текшелеп турап, йогурт, сарымсақ, паприка, лимон және тұзбен араластырып, тоңазытқышта кемінде 2 сағат ұста.", "uz": "Tovuqni kubik qilib toʻgʻra, qatiq, sarimsoq, paprika, limon va tuz bilan aralashtirib, kamida 2 soat sovutgichda saqla.", "tk": "Towugy kub edip dogra, gatyk, sarymsak, paprika, limon we duz bilen garyşdyryp, azyndan 2 sagat sowadyjyda sakla.", "ky": "Тоокту куб кылып туурап, йогурт, сарымсак, паприка, лимон жана туз менен аралаштырып, жок дегенде 2 саат муздаткычта калтыр.", "ka": "ქათამი კუბიკებად დაჭერი, აურიე მაწონთან, ნიორთან, პაპრიკასთან, ლიმონთან და მარილთან და სულ მცირე 2 საათი მაცივარში დატოვე."}, {"az": "Toyuğu bibər və soğanla növbə ilə şişə düz.", "ru": "Нанижи курицу на шпажки, чередуя с перцем и луком.", "en": "Thread onto skewers, alternating with pepper and onion.", "tr": "Tavuğu biber ve soğanla sırayla şişe diz.", "kk": "Тауықты бұрыш және пияз кезектестіріп шампурға тізіп шық.", "uz": "Tovuqni qalampir va piyoz bilan navbatma-navbat sixga ter.", "tk": "Towugy burç we sogan bilen nobatma-nobat şişe düz.", "ky": "Тоокту калемпир жана пияз менен кезектештирип шишке сай.", "ka": "ქათამი წიწაკასა და ხახვთან მონაცვლეობით შამფურზე ააცვი."}, {"az": "Qrildə və ya 220°C sobada 15–20 dəqiqə, arada çevirərək, içi tam bişənə qədər bişir.", "ru": "Готовь на гриле или в духовке при 220°C 15–20 минут, переворачивая, до полной готовности.", "en": "Grill or bake at 220°C for 15–20 minutes, turning, until cooked through.", "tr": "Izgarada ya da 220°C fırında 15–20 dakika, arada çevirerek, içi tamamen pişene kadar pişir.", "kk": "Грильде немесе 220°C пеште 15–20 минут, арасында аударып, іші толық піскенше пісір.", "uz": "Grilda yoki 220°C duxovkada 15–20 daqiqa, orada agʻdarib, ichi toʻliq pishguncha pishir.", "tk": "Grilde ýa-da 220°C peçde 15–20 minut, arasynda öwrüp, içi doly bişýänçä bişir.", "ky": "Грилде же 220°C духовкада 15–20 мүнөт, арасында оодарып туруп, ичи толук бышканча бышыр.", "ka": "გრილზე ან 220°C ღუმელში 15–20 წუთი, დროდადრო გადაბრუნებით, ბოლომდე შეწვამდე მოამზადე."}], "allergens": ["milk"]}',
  ),
];
